static
void kernel_atax(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    y[i] = 0;

  for (i = 0; i < _PB_M; i++)
    {
      tmp[i] = SCALAR_VAL(0.0);

      j = 0;
      while (j < _PB_N)
	{
	  size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - j));
	  vfloat32m1_t va = __riscv_vle32_v_f32m1(&A[i][j], vl);
	  vfloat32m1_t vx = __riscv_vle32_v_f32m1(&x[j], vl);
	  vfloat32m1_t vtmp = __riscv_vfmv_v_f_f32m1(0.0f, vl);

	  vfloat32m1_t vprod = __riscv_vfmul_vv_f32m1(va, vx, vl);
	  vfloat32m1_t vsum = __riscv_vfredosum_vs_f32m1_f32m1(vprod, __riscv_vfmv_v_f_f32m1(0.0f, vl), vl);
	  tmp[i] = tmp[i] + __riscv_vfmv_f_s_f32m1_f32(vsum);

	  j += (int)vl;
	}

      j = 0;
      while (j < _PB_N)
	{
	  size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - j));
	  vfloat32m1_t va = __riscv_vle32_v_f32m1(&A[i][j], vl);
	  vfloat32m1_t vtmp = __riscv_vfmv_v_f_f32m1((float)tmp[i], vl);
	  vfloat32m1_t vy = __riscv_vle32_v_f32m1(&y[j], vl);

	  vfloat32m1_t vprod = __riscv_vfmul_vv_f32m1(va, vtmp, vl);
	  vfloat32m1_t vsum = __riscv_vfredosum_vs_f32m1_f32m1(vprod, __riscv_vfmv_v_f_f32m1(0.0f, vl), vl);
	  y[j] = y[j] + __riscv_vfmv_f_s_f32m1_f32(vsum);

	  j += (int)vl;
	}
    }
#pragma endscop
}

