static
void kernel_cholesky(int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {

     for (j = 0; j < i; j++) {
        DATA_TYPE ajj = A[i][j];
        int kk = 0;

        for (; kk + 3 < j; kk += 4) {
           ajj -= A[i][kk] * A[j][kk];
           ajj -= A[i][kk + 1] * A[j][kk + 1];
           ajj -= A[i][kk + 2] * A[j][kk + 2];
           ajj -= A[i][kk + 3] * A[j][kk + 3];
        }
        for (; kk < j; ++kk) {
           ajj -= A[i][kk] * A[j][kk];
        }

        A[i][j] = ajj / A[j][j];
     }

     DATA_TYPE aii = A[i][i];
     int kk = 0;

     for (; kk + 3 < i; kk += 4) {
        aii -= A[i][kk] * A[i][kk];
        aii -= A[i][kk + 1] * A[i][kk + 1];
        aii -= A[i][kk + 2] * A[i][kk + 2];
        aii -= A[i][kk + 3] * A[i][kk + 3];
     }
     for (; kk < i; ++kk) {
        aii -= A[i][kk] * A[i][kk];
     }

     A[i][i] = SQRT_FUN(aii);
  }
#pragma endscop
}

#include <riscv_vector.h>
#include <math.h>

static
void kernel_correlation(int m, int n,
			DATA_TYPE float_n,
			DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
			DATA_TYPE POLYBENCH_2D(corr,M,M,m,m),
			DATA_TYPE POLYBENCH_1D(mean,M,m),
			DATA_TYPE POLYBENCH_1D(stddev,M,m))
{
  int i, j, k;

  DATA_TYPE eps = SCALAR_VAL(0.1);

#pragma scop
  for (j = 0; j < _PB_M; j++)
    {
      mean[j] = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_N; i++)
	mean[j] += data[i][j];
      mean[j] /= float_n;
    }

   for (j = 0; j < _PB_M; j++)
    {
      stddev[j] = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_N; i++)
        stddev[j] += (data[i][j] - mean[j]) * (data[i][j] - mean[j]);
      stddev[j] /= float_n;
      stddev[j] = SQRT_FUN(stddev[j]);


      stddev[j] = stddev[j] <= eps ? SCALAR_VAL(1.0) : stddev[j];
    }


  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      {
        data[i][j] -= mean[j];
        data[i][j] /= SQRT_FUN(float_n) * stddev[j];
      }


  for (i = 0; i < _PB_M-1; i++)
    {
      corr[i][i] = SCALAR_VAL(1.0);
      for (j = i+1; j < _PB_M; j++)
        {
          corr[i][j] = SCALAR_VAL(0.0);
          for (k = 0; k < _PB_N; k++)
            corr[i][j] += (data[k][i] * data[k][j]);
          corr[j][i] = corr[i][j];
        }
    }
  corr[_PB_M-1][_PB_M-1] = SCALAR_VAL(1.0);
#pragma endscop

}

