static
void kernel_durbin(int n,
		   DATA_TYPE POLYBENCH_1D(r,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
 DATA_TYPE z[N];
 DATA_TYPE alpha;
 DATA_TYPE beta;
 DATA_TYPE sum;

 int i,k;

#pragma scop
 y[0] = -r[0];
 beta = SCALAR_VAL(1.0);
 alpha = -r[0];

 for (k = 1; k < _PB_N; k++) {
   beta = (1-alpha*alpha)*beta;
   sum = SCALAR_VAL(0.0);

   int limit = k;
   int idx = 0;
   while (idx < limit) {
     size_t vl = __riscv_vsetvl_e64m1((size_t)(limit - idx));
     vfloat64m1_t vr = __riscv_vle64_v_f64m1((const double *)(r + (k - idx - (int)vl)), vl);
     vfloat64m1_t vy = __riscv_vle64_v_f64m1((const double *)(y + idx), vl);
     vfloat64m1_t vm = __riscv_vfmul_vv_f64m1(vr, vy, vl);
     sum += __riscv_vfredosum_vs_f64m1_f64m1_f64m1(vm, __riscv_vfmv_v_f_f64m1(0.0, vl), vl);
     idx += (int)vl;
   }

   alpha = - (r[k] + sum)/beta;

   int j = 0;
   while (j < k) {
     size_t vl = __riscv_vsetvl_e64m1((size_t)(k - j));
     vfloat64m1_t vyi = __riscv_vle64_v_f64m1((const double *)(y + j), vl);
     vfloat64m1_t vyk = __riscv_vle64_v_f64m1((const double *)(y + (k - j - (int)vl)), vl);
     vfloat64m1_t va = __riscv_vfmv_v_f_f64m1(alpha, vl);
     vfloat64m1_t vtmp = __riscv_vfmul_vv_f64m1(va, vyk, vl);
     vfloat64m1_t vz = __riscv_vfadd_vv_f64m1(vyi, vtmp, vl);
     __riscv_vse64_v_f64m1((double *)(z + j), vz, vl);
     j += (int)vl;
   }

   for (i=0; i<k; i++) {
     y[i] = z[i];
   }
   y[k] = alpha;
 }
#pragma endscop

}

