static
void kernel_fdtd_2d(int tmax,
		    int nx,
		    int ny,
		    DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int t, i, j;

#pragma scop
  const DATA_TYPE half = SCALAR_VAL(0.5);
  const DATA_TYPE seven = SCALAR_VAL(0.7);

  for (t = 0; t < _PB_TMAX; t++)
    {
      DATA_TYPE f = _fict_[t];

      for (j = 0; j < _PB_NY; j++)
	ey[0][j] = f;

      for (i = 1; i < _PB_NX; i++)
	{
	  DATA_TYPE* __restrict__ eyi = ey[i];
	  DATA_TYPE* __restrict__ eyim1 = ey[i - 1];
	  DATA_TYPE* __restrict__ hzi = hz[i];
	  DATA_TYPE* __restrict__ hzim1 = hz[i - 1];

	  int j = 0;
	  for (; j < _PB_NY; )
	    {
	      size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_NY - j));
	      vfloat64m1_t v_ey = __riscv_vle64_v_f64m1((const double*)(eyi + j), vl);
	      vfloat64m1_t v_hz = __riscv_vle64_v_f64m1((const double*)(hzi + j), vl);
	      vfloat64m1_t v_hzm1 = __riscv_vle64_v_f64m1((const double*)(hzim1 + j), vl);
	      vfloat64m1_t v_diff = __riscv_vfsub_vv_f64m1(v_hz, v_hzm1, vl);
	      v_ey = __riscv_vfsub_vv_f64m1(v_ey, __riscv_vfmul_vf_f64m1(v_diff, half, vl), vl);
	      __riscv_vse64_v_f64m1((double*)(eyi + j), v_ey, vl);
	      j += (int)vl;
	    }
	}

      for (i = 0; i < _PB_NX; i++)
	{
	  DATA_TYPE* __restrict__ exi = ex[i];
	  DATA_TYPE* __restrict__ hzi = hz[i];

	  int j = 1;
	  for (; j < _PB_NY; )
	    {
	      size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_NY - j));
	      vfloat64m1_t v_ex = __riscv_vle64_v_f64m1((const double*)(exi + j), vl);
	      vfloat64m1_t v_hz = __riscv_vle64_v_f64m1((const double*)(hzi + j), vl);
	      vfloat64m1_t v_hzm1 = __riscv_vle64_v_f64m1((const double*)(hzi + j - 1), vl);
	      vfloat64m1_t v_diff = __riscv_vfsub_vv_f64m1(v_hz, v_hzm1, vl);
	      v_ex = __riscv_vfsub_vv_f64m1(v_ex, __riscv_vfmul_vf_f64m1(v_diff, half, vl), vl);
	      __riscv_vse64_v_f64m1((double*)(exi + j), v_ex, vl);
	      j += (int)vl;
	    }
	}

      for (i = 0; i < _PB_NX - 1; i++)
	{
	  DATA_TYPE* __restrict__ hzi = hz[i];
	  DATA_TYPE* __restrict__ hzip1 = hz[i + 1];
	  DATA_TYPE* __restrict__ exi = ex[i];
	  DATA_TYPE* __restrict__ exip1 = ex[i + 1];
	  DATA_TYPE* __restrict__ eyi = ey[i];
	  DATA_TYPE* __restrict__ eyip1 = ey[i + 1];

	  int j = 0;
	  for (; j < _PB_NY - 1; )
	    {
	      size_t vl = __riscv_vsetvl_e64m1((size_t)((_PB_NY - 1) - j));
	      vfloat64m1_t v_hz = __riscv_vle64_v_f64m1((const double*)(hzi + j), vl);
	      vfloat64m1_t v_ex_next = __riscv_vle64_v_f64m1((const double*)(exip1 + j), vl);
	      vfloat64m1_t v_ex = __riscv_vle64_v_f64m1((const double*)(exi + j), vl);
	      vfloat64m1_t v_ey = __riscv_vle64_v_f64m1((const double*)(eyi + j), vl);
	      vfloat64m1_t v_ey_next = __riscv_vle64_v_f64m1((const double*)(eyip1 + j), vl);

	      vfloat64m1_t v_diff_x = __riscv_vfsub_vv_f64m1(v_ex_next, v_ex, vl);
	      vfloat64m1_t v_diff_y = __riscv_vfsub_vv_f64m1(v_ey_next, v_ey, vl);
	      vfloat64m1_t v_sum = __riscv_vfadd_vv_f64m1(v_diff_x, v_diff_y, vl);
	      v_hz = __riscv_vfsub_vv_f64m1(v_hz, __riscv_vfmul_vf_f64m1(v_sum, seven, vl), vl);
	      __riscv_vse64_v_f64m1((double*)(hzi + j), v_hz, vl);
	      j += (int)vl;
	    }
	}
    }
#pragma endscop
}

