static
void kernel_floyd_warshall(int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      for(i = 0; i < _PB_N; i++)
	{
	  DATA_TYPE* row_i = path[i];
	  DATA_TYPE* row_k = path[k];
	  DATA_TYPE dik = row_i[k];

	  j = 0;
	  while (j < _PB_N)
	    {
	      size_t vl = __riscv_vsetvl_e32m1((size_t)(_PB_N - j));
	      vuint32m1_t v_path = __riscv_vle32_v_u32m1((const uint32_t*)(row_i + j), vl);
	      vuint32m1_t v_krow = __riscv_vle32_v_u32m1((const uint32_t*)(row_k + j), vl);
	      vuint32m1_t v_dik = __riscv_vmv_v_x_u32m1((uint32_t)dik, vl);
	      vuint32m1_t v_sum = __riscv_vadd_vv_u32m1(v_dik, v_krow, vl);
	      vbool32_t mask = __riscv_vmsltu_vv_u32m1_b32(v_path, v_sum, vl);
	      vuint32m1_t v_min = __riscv_vmerge_vvm_u32m1(v_sum, v_path, mask, vl);
	      __riscv_vse32_v_u32m1((uint32_t*)(row_i + j), v_min, vl);
	      j += (int)vl;
	    }
	}
    }
#pragma endscop
}

