static
void kernel_gemm(int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < ni; i++) {
    j = 0;
    for (; j < nj; ) {
      size_t vl = __riscv_vsetvl_e64m1((size_t)(nj - j));
      vfloat64m1_t vc = __riscv_vle64_v_f64m1((const double *)&C[i][j], vl);
      vfloat64m1_t vbeta = __riscv_vfmv_v_f_f64m1(beta, vl);
      vc = __riscv_vfmul_vv_f64m1(vc, vbeta, vl);
      __riscv_vse64_v_f64m1((double *)&C[i][j], vc, vl);
      j += (int)vl;
    }

    for (k = 0; k < nk; k++) {
      j = 0;
      for (; j < nj; ) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(nj - j));
        vfloat64m1_t vc = __riscv_vle64_v_f64m1((const double *)&C[i][j], vl);
        vfloat64m1_t va = __riscv_vfmv_v_f_f64m1(A[i][k], vl);
        vfloat64m1_t vb = __riscv_vle64_v_f64m1((const double *)&B[k][j], vl);
        vfloat64m1_t valpha = __riscv_vfmv_v_f_f64m1(alpha, vl);
        vfloat64m1_t tmp = __riscv_vfmul_vv_f64m1(va, vb, vl);
        tmp = __riscv_vfmul_vv_f64m1(tmp, valpha, vl);
        vc = __riscv_vfadd_vv_f64m1(vc, tmp, vl);
        __riscv_vse64_v_f64m1((double *)&C[i][j], vc, vl);
        j += (int)vl;
      }
    }
  }
#pragma endscop
}

