static
void kernel_gesummv(int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      tmp[i] = SCALAR_VAL(0.0);
      y[i] = SCALAR_VAL(0.0);

      j = 0;
      while (j < _PB_N)
	{
	  size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - j));

	  vfloat64m1_t vx = __riscv_vle64_v_f64m1(&x[j], vl);

	  vfloat64m1_t va = __riscv_vle64_v_f64m1(&A[i][j], vl);
	  vfloat64m1_t vb = __riscv_vle64_v_f64m1(&B[i][j], vl);

	  vfloat64m1_t vtmp = __riscv_vfmul_vv_f64m1(va, vx, vl);
	  vfloat64m1_t vy   = __riscv_vfmul_vv_f64m1(vb, vx, vl);

	  vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, vl);
	  vfloat64m1_t vsum_tmp = __riscv_vfredosum_vs_f64m1_f64m1(vtmp, vzero, vl);
	  vfloat64m1_t vsum_y   = __riscv_vfredosum_vs_f64m1_f64m1(vy, vzero, vl);

	  tmp[i] = __riscv_vfmv_f_s_f64m1_f64(vsum_tmp);
	  y[i]   = __riscv_vfmv_f_s_f64m1_f64(vsum_y);

	  j += (int)vl;
	}

      y[i] = alpha * tmp[i] + beta * y[i];
    }
#pragma endscop
}

