static
void kernel_gramschmidt(int m, int n,
			DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
			DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
			DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;

  DATA_TYPE nrm;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      nrm = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_M; i++)
        nrm += A[i][k] * A[i][k];
      R[k][k] = SQRT_FUN(nrm);

      for (i = 0; i < _PB_M; i++)
        Q[i][k] = A[i][k] / R[k][k];

      for (j = k + 1; j < _PB_N; j++)
	{
	  R[k][j] = SCALAR_VAL(0.0);

	  int i = 0;
	  while (i < _PB_M)
	    {
	      size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_M - i));

	      vfloat64m1_t vq = __riscv_vle64_v_f64m1(&Q[i][k], vl);
	      vfloat64m1_t va = __riscv_vle64_v_f64m1(&A[i][j], vl);
	      vfloat64m1_t vr = __riscv_vfmv_v_f_f64m1(0.0, vl);

	      vr = __riscv_vfmacc_vv_f64m1(vr, va, vq, vl);

	      double sum = 0.0;
	      size_t t = 0;
	      for (; t < vl; ++t)
		sum += Q[i + (int)t][k] * A[i + (int)t][j];
	      R[k][j] += sum;

	      vfloat64m1_t vtmp = __riscv_vfmv_v_f_f64m1(R[k][j], vl);
	      vr = __riscv_vfsub_vv_f64m1(va, __riscv_vfmul_vv_f64m1(vq, vtmp, vl), vl);
	      __riscv_vse64_v_f64m1(&A[i][j], vr, vl);

	      i += (int)vl;
	    }
	}
    }
#pragma endscop
}

