static
void kernel_heat_3d(int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
    int t, i, j, k;
    const int N = n;

    for (t = 1; t <= tsteps; t++) {
        for (i = 1; i < N - 1; i++) {
            for (j = 1; j < N - 1; j++) {
                int kk = 1;
                for (; kk < N - 1; ) {
                    size_t vl = __riscv_vsetvl_e64m1((size_t)(N - 1 - kk));

                    vfloat64m1_t va_im1 = __riscv_vle64_v_f64m1(&A[i - 1][j][kk], vl);
                    vfloat64m1_t va     = __riscv_vle64_v_f64m1(&A[i][j][kk], vl);
                    vfloat64m1_t va_ip1 = __riscv_vle64_v_f64m1(&A[i + 1][j][kk], vl);

                    vfloat64m1_t vb_jm1 = __riscv_vle64_v_f64m1(&A[i][j - 1][kk], vl);
                    vfloat64m1_t vb_jp1 = __riscv_vle64_v_f64m1(&A[i][j + 1][kk], vl);
                    vfloat64m1_t vb_kp1 = __riscv_vle64_v_f64m1(&A[i][j][kk + 1], vl);
                    vfloat64m1_t vb_km1 = __riscv_vle64_v_f64m1(&A[i][j][kk - 1], vl);

                    vfloat64m1_t vtwo = __riscv_vfmv_v_f_f64m1(2.0, vl);
                    vfloat64m1_t vhalf = __riscv_vfmv_v_f_f64m1(0.125, vl);

                    vfloat64m1_t t1 = __riscv_vfmacc_vv_f64m1(va_im1, vtwo, va, vl);
                    t1 = __riscv_vfmsac_vv_f64m1(t1, vtwo, va_ip1, vl);
                    t1 = __riscv_vfmul_vf_f64m1(t1, 0.125, vl);

                    vfloat64m1_t t2 = __riscv_vfmacc_vv_f64m1(vb_jm1, vtwo, va, vl);
                    t2 = __riscv_vfmsac_vv_f64m1(t2, vtwo, vb_jp1, vl);
                    t2 = __riscv_vfmul_vf_f64m1(t2, 0.125, vl);

                    vfloat64m1_t t3 = __riscv_vfmacc_vv_f64m1(va, vtwo, va, vl);
                    t3 = __riscv_vfmsac_vv_f64m1(t3, vtwo, vb_km1, vl);
                    t3 = __riscv_vfmul_vf_f64m1(t3, 0.125, vl);

                    vfloat64m1_t acc = __riscv_vfmacc_vv_f64m1(t1, vhalf, t2, vl);
                    acc = __riscv_vfmacc_vv_f64m1(acc, vhalf, t3, vl);
                    acc = __riscv_vfmacc_vv_f64m1(acc, vhalf, va, vl);

                    __riscv_vse64_v_f64m1(&B[i][j][kk], acc, vl);

                    kk += (int)vl;
                }
            }
        }

        for (i = 1; i < N - 1; i++) {
            for (j = 1; j < N - 1; j++) {
                int kk = 1;
                for (; kk < N - 1; ) {
                    size_t vl = __riscv_vsetvl_e64m1((size_t)(N - 1 - kk));

                    vfloat64m1_t vb_im1 = __riscv_vle64_v_f64m1(&B[i - 1][j][kk], vl);
                    vfloat64m1_t vb     = __riscv_vle64_v_f64m1(&B[i][j][kk], vl);
                    vfloat64m1_t vb_ip1 = __riscv_vle64_v_f64m1(&B[i + 1][j][kk], vl);

                    vfloat64m1_t vb_jm1 = __riscv_vle64_v_f64m1(&B[i][j - 1][kk], vl);
                    vfloat64m1_t vb_jp1 = __riscv_vle64_v_f64m1(&B[i][j + 1][kk], vl);
                    vfloat64m1_t vb_kp1 = __riscv_vle64_v_f64m1(&B[i][j][kk + 1], vl);
                    vfloat64m1_t vb_km1 = __riscv_vle64_v_f64m1(&B[i][j][kk - 1], vl);

                    vfloat64m1_t vtwo = __riscv_vfmv_v_f_f64m1(2.0, vl);
                    vfloat64m1_t vhalf = __riscv_vfmv_v_f_f64m1(0.125, vl);

                    vfloat64m1_t t1 = __riscv_vfmacc_vv_f64m1(vb_im1, vtwo, vb, vl);
                    t1 = __riscv_vfmsac_vv_f64m1(t1, vtwo, vb_ip1, vl);
                    t1 = __riscv_vfmul_vf_f64m1(t1, 0.125, vl);

                    vfloat64m1_t t2 = __riscv_vfmacc_vv_f64m1(vb_jm1, vtwo, vb, vl);
                    t2 = __riscv_vfmsac_vv_f64m1(t2, vtwo, vb_jp1, vl);
                    t2 = __riscv_vfmul_vf_f64m1(t2, 0.125, vl);

                    vfloat64m1_t t3 = __riscv_vfmacc_vv_f64m1(vb, vtwo, vb, vl);
                    t3 = __riscv_vfmsac_vv_f64m1(t3, vtwo, vb_km1, vl);
                    t3 = __riscv_vfmul_vf_f64m1(t3, 0.125, vl);

                    vfloat64m1_t acc = __riscv_vfmacc_vv_f64m1(t1, vhalf, t2, vl);
                    acc = __riscv_vfmacc_vv_f64m1(acc, vhalf, t3, vl);
                    acc = __riscv_vfmacc_vv_f64m1(acc, vhalf, vb, vl);

                    __riscv_vse64_v_f64m1(&A[i][j][kk], acc, vl);

                    kk += (int)vl;
                }
            }
        }
    }
}

