void kernel_jacobi_1d(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_1D(A,N,n),
			    DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int t, i;
  const int N = n;

  for (t = 0; t < tsteps; t++)
    {
      int i = 1;
      for (; i + 3 < N - 1; i += 4)
	{
	  size_t vl = __riscv_vsetvl_e32m1(4);

	  vfloat32m1_t va0 = __riscv_vle32_v_f32m1(&A[i - 1], vl);
	  vfloat32m1_t va1 = __riscv_vle32_v_f32m1(&A[i], vl);
	  vfloat32m1_t va2 = __riscv_vle32_v_f32m1(&A[i + 1], vl);
	  vfloat32m1_t va3 = __riscv_vle32_v_f32m1(&A[i + 2], vl);

	  vfloat32m1_t vb0 = __riscv_vle32_v_f32m1(&B[i - 1], vl);
	  vfloat32m1_t vb1 = __riscv_vle32_v_f32m1(&B[i], vl);
	  vfloat32m1_t vb2 = __riscv_vle32_v_f32m1(&B[i + 1], vl);
	  vfloat32m1_t vb3 = __riscv_vle32_v_f32m1(&B[i + 2], vl);

	  vfloat32m1_t acc0 = __riscv_vfadd_vv_f32m1(va0, va1, vl);
	  acc0 = __riscv_vfadd_vv_f32m1(acc0, va2, vl);
	  vfloat32m1_t acc1 = __riscv_vfadd_vv_f32m1(vb0, vb1, vl);
	  acc1 = __riscv_vfadd_vv_f32m1(acc1, vb2, vl);

	  vfloat32m1_t acc2 = __riscv_vfadd_vv_f32m1(va1, va2, vl);
	  acc2 = __riscv_vfadd_vv_f32m1(acc2, va3, vl);
	  vfloat32m1_t acc3 = __riscv_vfadd_vv_f32m1(vb1, vb2, vl);
	  acc3 = __riscv_vfadd_vv_f32m1(acc3, vb3, vl);

	  acc0 = __riscv_vfmul_vf_f32m1(acc0, 0.33333f, vl);
	  acc1 = __riscv_vfmul_vf_f32m1(acc1, 0.33333f, vl);
	  acc2 = __riscv_vfmul_vf_f32m1(acc2, 0.33333f, vl);
	  acc3 = __riscv_vfmul_vf_f32m1(acc3, 0.33333f, vl);

	  __riscv_vse32_v_f32m1(&B[i], acc0, vl);
	  __riscv_vse32_v_f32m1(&B[i + 1], acc1, vl);
	  __riscv_vse32_v_f32m1(&B[i + 2], acc2, vl);
	  __riscv_vse32_v_f32m1(&B[i + 3], acc3, vl);
	}
      for (; i < N - 1; i++)
	B[i] = 0.33333 * (A[i-1] + A[i] + A[i + 1]);

      i = 1;
      for (; i + 3 < N - 1; i += 4)
	{
	  size_t vl = __riscv_vsetvl_e32m1(4);

	  vfloat32m1_t vb0 = __riscv_vle32_v_f32m1(&B[i - 1], vl);
	  vfloat32m1_t vb1 = __riscv_vle32_v_f32m1(&B[i], vl);
	  vfloat32m1_t vb2 = __riscv_vle32_v_f32m1(&B[i + 1], vl);
	  vfloat32m1_t vb3 = __riscv_vle32_v_f32m1(&B[i + 2], vl);

	  vfloat32m1_t acc0 = __riscv_vfadd_vv_f32m1(vb0, vb1, vl);
	  acc0 = __riscv_vfadd_vv_f32m1(acc0, vb2, vl);
	  vfloat32m1_t acc1 = __riscv_vfadd_vv_f32m1(vb1, vb2, vl);
	  acc1 = __riscv_vfadd_vv_f32m1(acc1, vb3, vl);

	  vfloat32m1_t acc2 = __riscv_vfadd_vv_f32m1(vb2, vb3, vl);
	  acc2 = __riscv_vfadd_vv_f32m1(acc2, __riscv_vle32_v_f32m1(&B[i + 3], vl), vl);
	  vfloat32m1_t acc3 = __riscv_vfadd_vv_f32m1(vb2, vb3, vl);
	  acc3 = __riscv_vfadd_vv_f32m1(acc3, __riscv_vle32_v_f32m1(&B[i + 4], vl), vl);

	  acc0 = __riscv_vfmul_vf_f32m1(acc0, 0.33333f, vl);
	  acc1 = __riscv_vfmul_vf_f32m1(acc1, 0.33333f, vl);
	  acc2 = __riscv_vfmul_vf_f32m1(acc2, 0.33333f, vl);
	  acc3 = __riscv_vfmul_vf_f32m1(acc3, 0.33333f, vl);

	  __riscv_vse32_v_f32m1(&A[i], acc0, vl);
	  __riscv_vse32_v_f32m1(&A[i + 1], acc1, vl);
	  __riscv_vse32_v_f32m1(&A[i + 2], acc2, vl);
	  __riscv_vse32_v_f32m1(&A[i + 3], acc3, vl);
	}
      for (; i < N - 1; i++)
	A[i] = 0.33333 * (B[i-1] + B[i] + B[i + 1]);
    }
}

#include <riscv_vector.h>
#include <polybench.h>

static
void kernel_jacobi_2d(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int t, i, j;
  const int N = n;
  const DATA_TYPE c02 = SCALAR_VAL(0.2);

  for (t = 0; t < tsteps; t++)
    {
      for (i = 1; i < N - 1; i++)
	{
	  j = 1;
	  for (; j < N - 1; )
	    {
	      size_t vl = __riscv_vsetvl_e64m1((size_t)(N - 1 - j));

	      vfloat64m1_t vA_j   = __riscv_vle64_v_f64m1(&A[i][j], vl);
	      vfloat64m1_t vA_lm1 = __riscv_vle64_v_f64m1(&A[i][j-1], vl);
	      vfloat64m1_t vA_jp1 = __riscv_vle64_v_f64m1(&A[i][j+1], vl);
	      vfloat64m1_t vA_ip1 = __riscv_vle64_v_f64m1(&A[i+1][j], vl);
	      vfloat64m1_t vA_im1 = __riscv_vle64_v_f64m1(&A[i-1][j], vl);

	      vfloat64m1_t vsum = __riscv_vfadd_vv_f64m1(vA_j, vA_lm1, vl);
	      vsum = __riscv_vfadd_vv_f64m1(vsum, vA_jp1, vl);
	      vsum = __riscv_vfadd_vv_f64m1(vsum, vA_ip1, vl);
	      vsum = __riscv_vfadd_vv_f64m1(vsum, vA_im1, vl);
	      vsum = __riscv_vfmul_vf_f64m1(vsum, c02, vl);

	      __riscv_vse64_v_f64m1(&B[i][j], vsum, vl);

	      j += (int)vl;
	    }
	}

      for (i = 1; i < N - 1; i++)
	{
	  j = 1;
	  for (; j < N - 1; )
	    {
	      size_t vl = __riscv_vsetvl_e64m1((size_t)(N - 1 - j));

	      vfloat64m1_t vB_j   = __riscv_vle64_v_f64m1(&B[i][j], vl);
	      vfloat64m1_t vB_lm1 = __riscv_vle64_v_f64m1(&B[i][j-1], vl);
	      vfloat64m1_t vB_jp1 = __riscv_vle64_v_f64m1(&B[i][j+1], vl);
	      vfloat64m1_t vB_ip1 = __riscv_vle64_v_f64m1(&B[i+1][j], vl);
	      vfloat64m1_t vB_im1 = __riscv_vle64_v_f64m1(&B[i-1][j], vl);

	      vfloat64m1_t vsum = __riscv_vfadd_vv_f64m1(vB_j, vB_lm1, vl);
	      vsum = __riscv_vfadd_vv_f64m1(vsum, vB_jp1, vl);
	      vsum = __riscv_vfadd_vv_f64m1(vsum, vB_ip1, vl);
	      vsum = __riscv_vfadd_vv_f64m1(vsum, vB_im1, vl);
	      vsum = __riscv_vfmul_vf_f64m1(vsum, c02, vl);

	      __riscv_vse64_v_f64m1(&A[i][j], vsum, vl);

	      j += (int)vl;
	    }
	}
    }
}

#include <riscv_vector.h>

static
void kernel_lu(int n,
	       DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    for (j = 0; j < i; j++) {
      DATA_TYPE aj = A[i][j];
      for (k = 0; k < j; k++) {
        aj -= A[i][k] * A[k][j];
      }
      A[i][j] = aj / A[j][j];
    }

    for (j = i; j < _PB_N; j++) {
      DATA_TYPE aij = A[i][j];
      for (k = 0; k < i; k++) {
        aij -= A[i][k] * A[k][j];
      }
      A[i][j] = aij;
    }
  }
#pragma endscop
}

#include <riscv_vector.h>
#include <stddef.h>

static
void kernel_ludcmp(int n,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(b,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j, k;

  DATA_TYPE w;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    for (j = 0; j < i; j++) {
       w = A[i][j];
       for (k = 0; k < j; k++) {
          w -= A[i][k] * A[k][j];
       }
        A[i][j] = w / A[j][j];
    }
   for (j = i; j < _PB_N; j++) {
       w = A[i][j];
       for (k = 0; k < i; k++) {
          w -= A[i][k] * A[k][j];
       }
       A[i][j] = w;
    }
  }

  for (i = 0; i < _PB_N; i++) {
     w = b[i];
     for (j = 0; j < i; j++)
        w -= A[i][j] * y[j];
     y[i] = w;
  }

   for (i = _PB_N-1; i >=0; i--) {
     w = y[i];
     for (j = i+1; j < _PB_N; j++)
        w -= A[i][j] * x[j];
     x[i] = w / A[i][i];
  }
#pragma endscop

}

#include <riscv_vector.h>
#include <polybench.h>

void kernel_mvt(int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE acc1 = x1[i];
    const DATA_TYPE* ai = A[i];
    j = 0;
    while (j < _PB_N) {
      size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - j));
      vfloat64m1_t vx = __riscv_vle64_v_f64m1((const double*)(ai + j), vl);
      vfloat64m1_t vy = __riscv_vle64_v_f64m1((const double*)(y_1 + j), vl);
      vfloat64m1_t vm = __riscv_vfmul_vv_f64m1(vx, vy, vl);

      double tmp[8];
      __riscv_vse64_v_f64m1(tmp, vm, vl);
      for (size_t k = 0; k < vl; ++k) acc1 += (DATA_TYPE)tmp[k];

      j += (int)vl;
    }
    x1[i] = acc1;
  }

  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE acc2 = x2[i];
    j = 0;
    while (j < _PB_N) {
      size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - j));

      double tmp_a[8];
      double tmp_y[8];
      for (size_t k = 0; k < vl; ++k) {
        tmp_a[k] = (double)A[j + (int)k][i];
        tmp_y[k] = (double)y_2[j + (int)k];
      }

      vfloat64m1_t vx = __riscv_vle64_v_f64m1(tmp_a, vl);
      vfloat64m1_t vy = __riscv_vle64_v_f64m1(tmp_y, vl);
      vfloat64m1_t vm = __riscv_vfmul_vv_f64m1(vx, vy, vl);

      double tmp[8];
      __riscv_vse64_v_f64m1(tmp, vm, vl);
      for (size_t k = 0; k < vl; ++k) acc2 += (DATA_TYPE)tmp[k];

      j += (int)vl;
    }
    x2[i] = acc2;
  }
#pragma endscop
}

#include <riscv_vector.h>
#include <stddef.h>
#include <stdint.h>

static inline int match(int a, int b) {
  return (a == b) ? 1 : -1;
}

static inline int max_score(int a, int b) {
  return a > b ? a : b;
}

static
void kernel_nussinov(int n, const int* seq, int** table)
{
  (void)n;
  for (int i = n - 1; i >= 0; --i) {
    for (int j = i + 1; j < n; ++j) {
      int best = table[i][j];

      if (j - 1 >= 0)
        best = max_score(best, table[i][j - 1]);
      if (i + 1 < n)
        best = max_score(best, table[i + 1][j]);

      if (j - 1 >= 0 && i + 1 < n) {
        if (i < j - 1)
          best = max_score(best, table[i + 1][j - 1] + match(seq[i], seq[j]));
        else
          best = max_score(best, table[i + 1][j - 1]);
      }

      int k = i + 1;
      for (; k < j; ++k) {
        best = max_score(best, table[i][k] + table[k + 1][j]);
      }

      table[i][j] = best;
    }
  }
}

#include <riscv_vector.h>

static
void kernel_seidel_2d(int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int t, i, j;

#pragma scop
  for (t = 0; t <= _PB_TSTEPS - 1; t++) {
    for (i = 1; i <= _PB_N - 2; i++) {
      for (j = 1; j <= _PB_N - 2; j++) {
        A[i][j] = (A[i - 1][j - 1] + A[i - 1][j] + A[i - 1][j + 1]
                   + A[i][j - 1] + A[i][j] + A[i][j + 1]
                   + A[i + 1][j - 1] + A[i + 1][j] + A[i + 1][j + 1]) / SCALAR_VAL(9.0);
      }
    }
  }
#pragma endscop
}

#include <riscv_vector.h>
#include <stddef.h>

static
void kernel_symm(int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE temp2;

#pragma scop
  for (i = 0; i < _PB_M; i++) {
    for (j = 0; j < _PB_N; j++) {
      temp2 = 0;
      for (k = 0; k < i; k++) {
        C[k][j] += alpha * B[i][j] * A[i][k];
        temp2 += B[k][j] * A[i][k];
      }
      C[i][j] = beta * C[i][j] + alpha * B[i][j] * A[i][i] + alpha * temp2;
    }
  }
#pragma endscop
}

#include <riscv_vector.h>
#include <stddef.h>

static
void kernel_syr2k(int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    for (j = 0; j <= i; j++)
      C[i][j] *= beta;

    for (k = 0; k < _PB_M; k++) {
      const DATA_TYPE aik = A[i][k];
      const DATA_TYPE bik = B[i][k];
      const DATA_TYPE aik_alpha = aik * alpha;
      const DATA_TYPE bik_alpha = bik * alpha;

      int j = 0;
      for (; j + 3 <= i; j += 4) {
	C[i][j]     += A[j][k] * aik_alpha + B[j][k] * bik_alpha;
	C[i][j + 1] += A[j + 1][k] * aik_alpha + B[j + 1][k] * bik_alpha;
	C[i][j + 2] += A[j + 2][k] * aik_alpha + B[j + 2][k] * bik_alpha;
	C[i][j + 3] += A[j + 3][k] * aik_alpha + B[j + 3][k] * bik_alpha;
      }
      for (; j <= i; ++j) {
	C[i][j] += A[j][k] * aik_alpha + B[j][k] * bik_alpha;
      }
    }
  }
#pragma endscop
}

#include <riscv_vector.h>
#include <stddef.h>

static
void kernel_syrk(int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    for (j = 0; j <= i; j++)
      C[i][j] *= beta;
    for (k = 0; k < _PB_M; k++) {
      for (j = 0; j <= i; j++)
        C[i][j] += alpha * A[i][k] * A[j][k];
    }
  }
#pragma endscop
}

#include <riscv_vector.h>
#include <polybench.h>

static
void kernel_trisolv(int n,
		    DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      x[i] = b[i];
      for (j = 0; j < i; j++)
        x[i] -= L[i][j] * x[j];
      x[i] = x[i] / L[i][i];
    }
#pragma endscop
}

#include <riscv_vector.h>
#include <stddef.h>

static
void kernel_trmm(int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_M; i++) {
    for (j = 0; j < _PB_N; j++) {
        for (k = i + 1; k < _PB_M; k++) {
            B[i][j] += A[k][i] * B[k][j];
        }
        B[i][j] = alpha * B[i][j];
    }
  }
#pragma endscop
}
